prompt --application/shared_components/user_interface/templates/region/collapsible_morph
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(594075282774864692)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TCollapsibleMorph #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading">',
'  <div class="amc-TCollapsibleMorph-shell">',
'    <header class="amc-TCollapsibleMorph-header">',
'      <h2 class="amc-TCollapsibleMorph-title" id="#REGION_STATIC_ID#_heading">',
'        <button type="button" class="amc-TCollapsibleMorph-toggle" aria-expanded="true" aria-controls="#REGION_STATIC_ID#_body"><span class="amc-TCollapsibleMorph-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TCollapsibleMorph-label">#TITLE#</span><span class="amc-TCollapsibleMorph-chevron" aria-hidden="true"></span></button>',
'      </h2>',
'      <div class="amc-TCollapsibleMorph-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'    </header>',
'    <div class="amc-TCollapsibleMorph-body" id="#REGION_STATIC_ID#_body">',
'      <div class="amc-TCollapsibleMorph-clip">',
'        <div class="amc-TCollapsibleMorph-content">#BODY##SUB_REGIONS#</div>',
'        <footer class="amc-TCollapsibleMorph-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'      </div>',
'    </div>',
'  </div>',
'</section>'))
,p_page_plug_template_name=>'AMC Collapsible Morph'
,p_internal_name=>'AMC_TPL_COLLAPSIBLE_MORPH'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-collapsible-morph.js'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-collapsible-morph.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Collapsible region template. The region title is a button with aria-expanded and aria-controls inside the heading; clicking it or pressing Enter or Space collapses the card into a pill that holds only the icon, title and chevron, and expands it again. The body is clipped only while it is collapsed or animating and is hidden from keyboard and screen readers when collapsed; when open it is never clipped, so report menus, date pickers and popups inside work normally. After expanding, a resize event lets charts redraw. Without JavaScript the region renders expanded and cannot collapse. Buttons in Help, Edit, Change, Copy, Delete and Create sit in the header and hide while collapsed; Previous, Close and Next sit in the footer. Template options: Collapsed by default applies on page load; Remember state keeps the collapsed or expanded state per page and region for the browser session; Pill at end places the collapsed pill at the inline end; Primary pill colors the collapsed pill with the primary color; No body padding. Under prefers-reduced-motion the change is instant; JavaScript API: amcTplCollapsibleMorph.collapse(element) and expand(element).'
);
end;
/
